 * Resolve a pointer against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string} pointer JSON Pointer text
 * @returns {unknown} the value the pointer selects
 */
export function resolve(document, pointer) {
  if (pointer === '') return document;

  const tokens = parsePointer(pointer);
  let current = document;
  let path = '';

  for (const token of tokens) {
    path += '/' + formatPointer([token]);

    if (Array.isArray(current)) {
      // Validate array index
      if (token === '-' || token === '' || /\s/.test(token)) {
        throw new PointerError(`invalid array index: ${token} at ${path}`, pointer);
      }
      if (!/^\d+$/.test(token) || (token.length > 1 && token[0] === '0')) {
        throw new PointerError(`invalid array index: ${token} at ${path}`, pointer);
      }
      const index = parseInt(token, 10);
      if (index >= current.length) {
        throw new PointerError(`index out of range: ${index} at ${path}`, pointer);
      }
      current = current[index];
    } else if (current !== null && typeof current === 'object') {
      // Handle object
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        throw new PointerError(`missing property: ${token} at ${path}`, pointer);
      }
      current = current[token];
    } else {
      // Cannot index into primitive types
      const type = current === null ? 'null' : typeof current;
      throw new PointerError(`cannot index into ${type} at ${path}`, pointer);
    }
  }

  return current;
}"}

